<?php require_once __DIR__.'/../includes/app-release.php'; if(empty($paginaCuenta)||!empty($paginaReportes)||!empty($paginaTops))return;if(!function_exists('current_user')||!current_user()||!isset($roleLabels[$navRole??'']))return; $release=app_release(); ?>
